const req = $input.first().json;
const data = req.data || {};
const chapterNum = Number(data.chapterNumber || 6);
const focus = data.targetFocus || (chapterNum === 6 ? 'chapter-6-salts' : 'chapter-8-alloys');

let worksheet = {};

if (chapterNum === 6 || focus === 'chapter-6-salts') {
  worksheet = {
    title: 'SPM Intensive Drill: Form 4 Chapter 6 (Acid, Base and Salt)',
    chapter: 'Acid, Base and Salt',
    chapterNumber: 6,
    questions: [
      {
        id: 'spm-ch6-q1',
        text: 'A student carried out an experiment to prepare copper(II) sulphate salt. Name the suitable acid and metal oxide used as reactants.',
        type: 'structured',
        marks: 2,
        markingScheme: [
          'Sulphuric acid / H2SO4',
          'Copper(II) oxide / CuO'
        ],
        subtopic: '6.9 Preparation of Soluble Salts'
      },
      {
        id: 'spm-ch6-q2',
        text: 'Explain why lead(II) sulphate cannot be prepared using the acid + metal oxide reaction in an school laboratory.',
        type: 'structured',
        marks: 2,
        markingScheme: [
          'Lead(II) sulphate is an insoluble salt',
          'An insoluble layer of lead(II) sulphate covers the lead oxide reactant, stopping further reaction'
        ],
        subtopic: '6.9 Preparation of Salts'
      },
      {
        id: 'spm-ch6-q3',
        text: '25.0 cm3 of 0.1 mol dm-3 sodium hydroxide solution is neutralised by 20.0 cm3 of sulphuric acid. Calculate the molarity of the sulphuric acid.',
        type: 'structured',
        marks: 3,
        markingScheme: [
          'Balanced chemical equation: H2SO4 + 2NaOH -> Na2SO4 + 2H2O',
          'Apply formula: (Ma * 20.0) / (0.1 * 25.0) = 1 / 2',
          'Ma = 0.0625 mol dm-3'
        ],
        subtopic: '6.7 Neutralisation & Titration'
      }
    ]
  };
} else {
  worksheet = {
    title: 'SPM Intensive Drill: Form 4 Chapter 8 (Manufactured Substances in Industry)',
    chapter: 'Manufactured Substances in Industry',
    chapterNumber: 8,
    questions: [
      {
        id: 'spm-ch8-q1',
        text: 'Pure copper is ductile and malleable, while bronze is much harder. In terms of atomic arrangement, explain why bronze is harder than pure copper.',
        type: 'structured',
        marks: 4,
        markingScheme: [
          'Pure copper atoms are identical in size and arranged in orderly layers',
          'Layers of copper atoms easily slide over one another when force is applied',
          'In bronze, foreign tin atoms of different size disrupt the orderly arrangement of copper atoms',
          'This prevents the layers of atoms from sliding easily over each other'
        ],
        subtopic: '8.1 Alloy Structure and Properties'
      },
      {
        id: 'spm-ch8-q2',
        text: 'Laboratory apparatus such as boiling tubes are made of borosilicate glass instead of soda-lime glass. State two reasons why borosilicate glass is preferred for heating.',
        type: 'structured',
        marks: 2,
        markingScheme: [
          'Borosilicate glass has a lower thermal expansion coefficient (does not crack easily when heated / high thermal shock resistance)',
          'Borosilicate glass has higher chemical resistance towards acids and alkalis'
        ],
        subtopic: '8.2 Glass and Ceramics'
      }
    ]
  };
}

return [{
  json: worksheet
}];
